package de.local.tapoviewer;

import android.content.*;
import android.media.*;
import androidx.media3.common.*;
import androidx.media3.decoder.DecoderInputBuffer;
import androidx.test.platform.app.InstrumentationRegistry;
import androidx.test.ext.junit.runners.AndroidJUnit4;
import org.junit.*;
import org.junit.runner.RunWith;
import java.io.*;
import java.nio.*;
import java.util.*;
import java.util.concurrent.*;
import static org.junit.Assert.*;

@RunWith(AndroidJUnit4.class)
@androidx.annotation.OptIn(markerClass=androidx.media3.common.util.UnstableApi.class)
public class AudioConversionDeviceTest {
    private Context context;private String prefix;private final List<File> files=new ArrayList<>();
    @Before public void setup(){context=InstrumentationRegistry.getInstrumentation().getTargetContext();prefix="AudioConvertTest_"+UUID.randomUUID().toString().replace("-","");}
    @After public void clean(){for(File file:files){if(file.getParentFile().equals(LocalMedia.directory(context)))LocalMedia.delete(context,file);else file.delete();}for(File file:LocalMedia.list(context))if(file.getName().startsWith(prefix))LocalMedia.delete(context,file);}
    private File fixture(String name)throws Exception{File file=File.createTempFile("audio-fixture-",".bin",context.getCacheDir());files.add(file);try(InputStream in=InstrumentationRegistry.getInstrumentation().getContext().getAssets().open(name);OutputStream out=new FileOutputStream(file)){byte[] buffer=new byte[8192];int n;while((n=in.read(buffer))!=-1)out.write(buffer,0,n);}return file;}
    private Format format(MediaFormat source){Format.Builder builder=new Format.Builder().setSampleMimeType(source.getString(MediaFormat.KEY_MIME));if(source.containsKey(MediaFormat.KEY_WIDTH))builder.setWidth(source.getInteger(MediaFormat.KEY_WIDTH)).setHeight(source.getInteger(MediaFormat.KEY_HEIGHT));if(source.containsKey(MediaFormat.KEY_SAMPLE_RATE))builder.setSampleRate(source.getInteger(MediaFormat.KEY_SAMPLE_RATE)).setChannelCount(source.getInteger(MediaFormat.KEY_CHANNEL_COUNT));List<byte[]> csd=new ArrayList<>();for(int i=0;source.containsKey("csd-"+i);i++){ByteBuffer bytes=source.getByteBuffer("csd-"+i).duplicate();byte[] data=new byte[bytes.remaining()];bytes.get(data);csd.add(data);}return builder.setInitializationData(csd).build();}
    private static final class Writer implements AudioToAac.Output,AutoCloseable{MediaMuxer muxer;int track;long last=-1;Writer(File file)throws Exception{muxer=new MediaMuxer(file.getAbsolutePath(),MediaMuxer.OutputFormat.MUXER_OUTPUT_MPEG_4);}public void format(MediaFormat format){track=muxer.addTrack(format);muxer.start();}public void sample(ByteBuffer bytes,MediaCodec.BufferInfo info){info.presentationTimeUs=Math.max(info.presentationTimeUs,last+1);muxer.writeSampleData(track,bytes,info);last=info.presentationTimeUs;}public void close(){muxer.stop();muxer.release();}}
    @Test public void convertsG711AndPcmToDecodableAac()throws Exception{for(String mime:new String[]{MimeTypes.AUDIO_ALAW,MimeTypes.AUDIO_MLAW,MimeTypes.AUDIO_RAW}){File result=LocalMedia.create(context,prefix,".mp4");files.add(result);Format source=new Format.Builder().setSampleMimeType(mime).setSampleRate(8000).setChannelCount(1).setPcmEncoding(C.ENCODING_PCM_16BIT).build();try(Writer writer=new Writer(result);AudioToAac converter=new AudioToAac(source,writer)){for(int packet=0;packet<100;packet++){boolean raw=mime.equals(MimeTypes.AUDIO_RAW);ByteBuffer bytes=ByteBuffer.allocate(160*(raw?2:1)).order(ByteOrder.LITTLE_ENDIAN);for(int i=0;i<160;i++){short sample=(short)(Math.sin((packet*160+i)*2*Math.PI*440/8000)*9000);if(raw)bytes.putShort(sample);else bytes.put((byte)(mime.equals(MimeTypes.AUDIO_ALAW)?(i%20<10?0xaa:0x2a):(i%20<10?0x80:0)));}converter.input(bytes.array(),packet*20000L);}converter.finish();}assertAacDecodes(result,8000);}}
    @Test public void decodesMp3AndEncodesAac()throws Exception{for(String name:new String[]{"audio-test.mp3","audio-test.m4a"}){File input=fixture(name),result=LocalMedia.create(context,prefix,".mp4");files.add(result);MediaExtractor extractor=new MediaExtractor();try{extractor.setDataSource(input.getAbsolutePath());extractor.selectTrack(0);Format source=format(extractor.getTrackFormat(0));try(Writer writer=new Writer(result);AudioToAac converter=new AudioToAac(source,writer)){ByteBuffer sample=ByteBuffer.allocate(65536);int count;while((count=extractor.readSampleData(sample,0))>0){byte[] bytes=new byte[count];sample.position(0);sample.get(bytes);converter.input(bytes,extractor.getSampleTime());sample.clear();extractor.advance();}converter.finish();}}finally{extractor.release();}assertAacDecodes(result,name.endsWith(".mp3")?16000:44100);}}
    @Test public void originalVideoRemainsUnchangedWhilePcmAudioIsConverted()throws Exception{File input=fixture("video-test.mp4");MediaExtractor extractor=new MediaExtractor();CountDownLatch done=new CountDownLatch(1);File[] result={null};String[] error={null};try{extractor.setDataSource(input.getAbsolutePath());extractor.selectTrack(0);OriginalRecorder.Tap tap=new OriginalRecorder.Tap();tap.video=format(extractor.getTrackFormat(0));tap.audio=new Format.Builder().setSampleMimeType(MimeTypes.AUDIO_RAW).setSampleRate(16000).setChannelCount(1).setPcmEncoding(C.ENCODING_PCM_16BIT).build();OriginalRecorder recorder=new OriginalRecorder(context,prefix,tap,(file,message)->{result[0]=file;error[0]=message;done.countDown();});tap.recorder=recorder;ByteBuffer video=ByteBuffer.allocate(1024*1024);long audioTime=0;int count;while((count=extractor.readSampleData(video,0))>0){long time=extractor.getSampleTime();DecoderInputBuffer frame=new DecoderInputBuffer(DecoderInputBuffer.BUFFER_REPLACEMENT_MODE_NORMAL);frame.ensureSpaceForWrite(count);video.position(0);video.limit(count);frame.data.put(video);frame.timeUs=time;frame.setFlags((extractor.getSampleFlags()&MediaExtractor.SAMPLE_FLAG_SYNC)!=0?C.BUFFER_FLAG_KEY_FRAME:0);tap.sample(tap.video,frame);while(audioTime<=time){DecoderInputBuffer sound=new DecoderInputBuffer(DecoderInputBuffer.BUFFER_REPLACEMENT_MODE_NORMAL);sound.ensureSpaceForWrite(640);for(int i=0;i<320;i++)sound.data.order(ByteOrder.LITTLE_ENDIAN).putShort((short)(Math.sin((audioTime/1000000.0+i/16000.0)*440*2*Math.PI)*10000));sound.timeUs=audioTime;tap.sample(tap.audio,sound);audioTime+=20000;}video.clear();extractor.advance();}tap.recorder=null;recorder.finish();assertTrue(done.await(20,TimeUnit.SECONDS));assertNull(error[0]);assertNotNull(result[0]);files.add(result[0]);assertAacDecodes(result[0],16000);MediaMetadataRetriever reader=new MediaMetadataRetriever();try{reader.setDataSource(result[0].getAbsolutePath());assertEquals("320",reader.extractMetadata(MediaMetadataRetriever.METADATA_KEY_VIDEO_WIDTH));android.graphics.Bitmap image=reader.getFrameAtTime();assertNotNull(image);image.recycle();}finally{reader.release();}}finally{extractor.release();}}
    private void assertAacDecodes(File file,int rate)throws Exception{MediaExtractor extractor=new MediaExtractor();MediaCodec decoder=null;try{extractor.setDataSource(file.getAbsolutePath());int audio=-1;for(int i=0;i<extractor.getTrackCount();i++)if(extractor.getTrackFormat(i).getString(MediaFormat.KEY_MIME).startsWith("audio/"))audio=i;assertTrue("Missing AAC track",audio>=0);MediaFormat format=extractor.getTrackFormat(audio);assertEquals(MimeTypes.AUDIO_AAC,format.getString(MediaFormat.KEY_MIME));assertEquals(rate,format.getInteger(MediaFormat.KEY_SAMPLE_RATE));extractor.selectTrack(audio);decoder=MediaCodec.createDecoderByType(MimeTypes.AUDIO_AAC);decoder.configure(format,null,null,0);decoder.start();boolean inputEnded=false,outputEnded=false;int decoded=0;long energy=0,deadline=System.currentTimeMillis()+15000;MediaCodec.BufferInfo info=new MediaCodec.BufferInfo();while(!outputEnded&&System.currentTimeMillis()<deadline){if(!inputEnded){int index=decoder.dequeueInputBuffer(10000);if(index>=0){ByteBuffer input=decoder.getInputBuffer(index);int size=extractor.readSampleData(input,0);if(size<0){decoder.queueInputBuffer(index,0,0,0,MediaCodec.BUFFER_FLAG_END_OF_STREAM);inputEnded=true;}else{decoder.queueInputBuffer(index,0,size,extractor.getSampleTime(),0);extractor.advance();}}}int output=decoder.dequeueOutputBuffer(info,10000);if(output>=0){ByteBuffer bytes=decoder.getOutputBuffer(output).order(ByteOrder.LITTLE_ENDIAN);bytes.position(info.offset);bytes.limit(info.offset+info.size);decoded+=info.size;while(bytes.remaining()>=2)energy+=Math.abs((int)bytes.getShort());outputEnded=(info.flags&MediaCodec.BUFFER_FLAG_END_OF_STREAM)!=0;decoder.releaseOutputBuffer(output,false);}}assertTrue("AAC output must decode to PCM",decoded>rate);assertTrue("Converted audio must not be silent",energy>10000);assertTrue(outputEnded);}finally{if(decoder!=null){try{decoder.stop();}catch(Exception ignored){}decoder.release();}extractor.release();}}
}
